+fn moved_prism(dx: f64) -> Mesh {
+    let f = prism()
+        .facets
+        .iter()
+        .map(|t| {
+            let m = |p: Point3| Point3::new(p.x + dx, p.y, p.z);
+            Triangle::new(m(t.a), m(t.b), m(t.c))
+        })
+        .collect();
+    Mesh::from_facets(f)
+}
